<?php
function appointment_history(int $id,int $actor,string $action,array $details): void { execute('INSERT INTO lich_hen_lich_su(lich_hen_id,nguoi_thao_tac_id,hanh_dong,chi_tiet)VALUES(?,?,?,?)',[$id,$actor,$action,json_encode($details,JSON_UNESCAPED_UNICODE)]); }
function slot_valid(string $vin,int $staff,string $start,string $end,int $exclude=0): void { must($end>$start&&strtotime($start)>time(),'Lịch cần ở tương lai và giờ kết thúc sau giờ bắt đầu.');must(strtotime($end)-strtotime($start)<=4*3600,'Lịch xem xe tối đa 4 giờ.');$hit=db_one("SELECT id FROM lich_hen WHERE id<>? AND trang_thai='DA_XAC_NHAN' AND (so_khung_vin=? OR nhan_vien_id=?) AND bat_dau<? AND ket_thuc>? LIMIT 1",[$exclude,$vin,$staff,$end,$start]);must(!$hit,'VIN hoặc nhân viên đã có lịch trùng giờ.'); }
function appointment_action(array $u,array $p): void {
 $action=input($p,'action');$id=(int)input($p,'id');
 if($action==='create'){must($u['quyen']==='KHACH_HANG','Chỉ khách hàng tạo lịch.',403);$vin=input($p,'vin');$start=valid_date(input($p,'bat_dau'));$end=valid_date(input($p,'ket_thuc'));must($end>$start&&strtotime($start)>time()&&strtotime($end)-strtotime($start)<=14400,'Thời gian hẹn chưa hợp lệ.');transaction(function()use($u,$vin,$start,$end,$p){$x=db_one('SELECT x.* FROM xe x JOIN cau_hinh_xe c ON c.ma_cau_hinh=x.ma_cau_hinh JOIN dong_xe d ON d.ma_dong_xe=x.ma_dong_xe WHERE x.so_khung_vin=? AND c.hien_thi=1 AND d.hien_thi=1 FOR UPDATE',[$vin]);must($x&&$x['trang_thai']!=='DA_BAN_GIAO','Xe không còn phù hợp để đặt lịch.');execute('INSERT INTO lich_hen(khach_hang_id,so_khung_vin,ma_showroom,bat_dau,ket_thuc,yeu_cau)VALUES(?,?,?,?,?,?)',[$u['id'],$vin,$x['ma_showroom'],$start,$end,valid_text(input($p,'ghi_chu'),1500,false)]);appointment_history(insert_id(),(int)$u['id'],'TAO',[$start,$end]);});return;}
 transaction(function()use($u,$p,$action,$id){$hint=db_one('SELECT * FROM lich_hen WHERE id=?',[$id]);must((bool)$hint,'Không tìm thấy lịch.');$x=db_one('SELECT * FROM xe WHERE so_khung_vin=? FOR UPDATE',[$hint['so_khung_vin']]);$staff=$u['quyen']==='KHACH_HANG'?(int)$hint['nhan_vien_id']:($u['quyen']==='ADMIN'?(int)(input($p,'nhan_vien_id')?:$hint['nhan_vien_id']):(int)$u['id']);if($staff)db_one('SELECT id FROM tai_khoan WHERE id=? FOR UPDATE',[$staff]);$r=db_one('SELECT * FROM lich_hen WHERE id=? FOR UPDATE',[$id]);$customer=$u['quyen']==='KHACH_HANG';must($customer?(int)$r['khach_hang_id']===(int)$u['id']:($u['quyen']==='ADMIN'||(scope_showroom($u,$r['ma_showroom'])&&($r['nhan_vien_id']===null||(int)$r['nhan_vien_id']===(int)$u['id']))),'Lịch ngoài phạm vi truy cập.',403);must(!in_array($r['trang_thai'],['DA_HUY','DA_DEN','KHONG_DEN'],true),'Lịch đã kết thúc.');
 if($action==='request_cancel'){must($customer,'Thao tác không hợp lệ.');execute("UPDATE lich_hen SET yeu_cau_loai='HUY',yeu_cau=?,nguoi_de_xuat_id=? WHERE id=?",[valid_text(input($p,'ghi_chu'),1500),$u['id'],$id]);}
 elseif($action==='cancel'){must(!$customer,'Nhân viên cần xác nhận hủy.',403);execute("UPDATE lich_hen SET trang_thai='DA_HUY',yeu_cau_loai=NULL WHERE id=?",[$id]);}
 elseif($action==='propose'){$start=valid_date(input($p,'bat_dau'));$end=valid_date(input($p,'ket_thuc'));must($end>$start&&strtotime($start)>time()&&strtotime($end)-strtotime($start)<=14400,'Giờ đề xuất chưa hợp lệ hoặc dài hơn 4 giờ.');if(!$customer){$employee=db_one("SELECT * FROM tai_khoan WHERE id=? AND quyen='NHAN_VIEN' AND trang_thai='HOAT_DONG'",[$staff]);must($employee&&scope_showroom($employee,$r['ma_showroom']),'Chọn nhân viên có phạm vi showroom phù hợp.');execute('UPDATE lich_hen SET nhan_vien_id=? WHERE id=?',[$staff,$id]);}execute("UPDATE lich_hen SET de_xuat_bat_dau=?,de_xuat_ket_thuc=?,yeu_cau_loai='DOI_GIO',nguoi_de_xuat_id=? WHERE id=?",[$start,$end,$u['id'],$id]);}
 elseif(in_array($action,['confirm','accept'],true)){
  if($action==='confirm')must(!$customer,'Nhân viên cần xác nhận lịch.',403);else must($r['yeu_cau_loai']==='DOI_GIO'&&(int)$r['nguoi_de_xuat_id']!==(int)$u['id']&&($customer||$u['quyen']==='ADMIN'||(int)$r['nguoi_de_xuat_id']===(int)$r['khach_hang_id']),'Chưa có đề xuất từ phía còn lại.');
  $employee=db_one("SELECT * FROM tai_khoan WHERE id=? AND quyen='NHAN_VIEN' AND trang_thai='HOAT_DONG'",[$staff]);must($employee&&scope_showroom($employee,$r['ma_showroom']),'Chọn nhân viên có phạm vi showroom phù hợp.');must($x['trang_thai']!=='DA_BAN_GIAO'&&$x['ma_showroom']===$r['ma_showroom'],'Xe đã giao hoặc đã chuyển showroom. Cần tạo lịch mới.');$start=$action==='accept'?$r['de_xuat_bat_dau']:$r['bat_dau'];$end=$action==='accept'?$r['de_xuat_ket_thuc']:$r['ket_thuc'];slot_valid($r['so_khung_vin'],$staff,$start,$end,$id);execute("UPDATE lich_hen SET nhan_vien_id=?,bat_dau=?,ket_thuc=?,trang_thai='DA_XAC_NHAN',yeu_cau_loai=NULL,de_xuat_bat_dau=NULL,de_xuat_ket_thuc=NULL WHERE id=?",[$staff,$start,$end,$id]);
 }elseif($action==='result'){must(!$customer&&$r['trang_thai']==='DA_XAC_NHAN'&&strtotime($r['ket_thuc'])<=time(),'Chỉ ghi kết quả của lịch đã xác nhận sau giờ hẹn.',403);$status=input($p,'ket_qua_loai');must(in_array($status,['DA_DEN','KHONG_DEN'],true),'Kết quả chưa hợp lệ.');execute('UPDATE lich_hen SET trang_thai=?,ket_qua=? WHERE id=?',[$status,valid_text(input($p,'ghi_chu'),1500,false),$id]);}
 else throw new AppError('Thao tác không hợp lệ.');appointment_history($id,(int)$u['id'],$action,['truoc'=>$r,'yeu_cau'=>array_intersect_key($p,array_flip(['bat_dau','ket_thuc','ghi_chu']))]);
 });
}
